// ─── File: src/test/java/com/bank/lockprofile/LockProfilingTest.java ───
package com.bank.lockprofile;

import org.junit.jupiter.api.Test;
import java.lang.management.*;
import java.util.concurrent.*;
import java.util.concurrent.locks.*;
import static org.assertj.core.api.Assertions.*;

class LockProfilingTest {

    // ═══ ReentrantLock contention: WAITING, not BLOCKED! ═══
    @Test
    void reentrantLock_waitingNotBlocked() throws InterruptedException {
        ReentrantLock lock = new ReentrantLock();
        CountDownLatch held = new CountDownLatch(1);

        Thread holder = new Thread(() -> {
            lock.lock();
            try { held.countDown(); Thread.sleep(2000); }
            catch (InterruptedException e) {}
            finally { lock.unlock(); }
        });
        holder.start();
        held.await();

        Thread waiter = new Thread(() -> {
            lock.lock();  // will WAIT (parked by AQS!)
            lock.unlock();
        }, "lock-waiter");
        waiter.start();
        Thread.sleep(200);

        // waiter is WAITING, NOT BLOCKED!
        assertThat(waiter.getState()).isEqualTo(Thread.State.WAITING);
        // synchronized would show BLOCKED!

        holder.interrupt(); holder.join(); waiter.join(3000);
    }

    // ═══ synchronized contention: BLOCKED! ═══
    @Test
    void synchronized_blocked() throws InterruptedException {
        Object lock = new Object();
        CountDownLatch held = new CountDownLatch(1);

        Thread holder = new Thread(() -> {
            synchronized (lock) { held.countDown(); try { Thread.sleep(2000); } catch (InterruptedException e) {} }
        });
        holder.start();
        held.await();

        Thread waiter = new Thread(() -> { synchronized (lock) {} }, "sync-waiter");
        waiter.start();
        Thread.sleep(200);

        assertThat(waiter.getState()).isEqualTo(Thread.State.BLOCKED);  // BLOCKED!
        holder.interrupt(); holder.join(); waiter.join(3000);
    }

    // ═══ Measure contention time ═══
    @Test
    void measureContentionTime() throws InterruptedException {
        ReentrantLock lock = new ReentrantLock();
        lock.lock();

        long[] waitTime = {0};
        Thread waiter = new Thread(() -> {
            long start = System.nanoTime();
            lock.lock();  // will wait!
            waitTime[0] = (System.nanoTime() - start) / 1_000_000;
            lock.unlock();
        });
        waiter.start();
        Thread.sleep(500);
        lock.unlock();
        waiter.join();

        System.out.println("Lock contention wait: " + waitTime[0] + "ms");
        assertThat(waitTime[0]).isGreaterThanOrEqualTo(400);
    }

    // ═══ ThreadMXBean: findDeadlockedThreads detects BOTH types ═══
    @Test
    void threadMXBean_detectsBothTypes() {
        ThreadMXBean tmx = ManagementFactory.getThreadMXBean();
        long[] deadlocked = tmx.findDeadlockedThreads();  // finds sync + ReentrantLock!
        assertThat(deadlocked).isNull();  // no deadlock
    }
}
